  'Creator tools' => 'Công cụ dành cho người sáng tạo',
  'Creator uploads' => 'Tải lên của người sáng tạo',
  'Creators can upload videos, manage visibility, add thumbnails and captions, publish scheduled content, review their library, and track content from Creator Studio.' => 'Người sáng tạo có thể tải video lên, quản lý chế độ hiển thị, thêm hình thu nhỏ và chú thích, xuất bản nội dung đã lên lịch, xem lại thư viện của họ và theo dõi nội dung từ Creator Studio.',
  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'Người sáng tạo phải cung cấp tiêu đề, mô tả, danh mục, ngôn ngữ, hình thu nhỏ, chú thích, chế độ hiển thị và cài đặt lịch trình chính xác. Các video đã lên lịch sẽ không được công khai cho đến khi đến thời gian đã lên lịch và xử lý thành công.',
  'curl --request GET \\\\ --url' => 'cuộn tròn --request NHẬN \\\\ --url',
  'Current upload categories' => 'Danh mục tải lên hiện tại',
