  'Playback' => 'Phát lại',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Tiến trình phát lại, trạng thái xem sau, lượt thích, nhận xét, đăng ký, thông báo và phân tích của quản trị viên được lưu trữ trong cơ sở dữ liệu khi được liên kết với các tính năng nền tảng đã được xác thực.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Phát lại, nhận xét, lượt thích, xem sau, đăng ký, thông báo, tin nhắn, danh sách phát và cài đặt ngôn ngữ có sẵn thông qua menu tài khoản và điều hướng chính.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub là nền tảng video để tải lên, xem, lên lịch, quản lý và kiểm duyệt nội dung của người sáng tạo từ một tài khoản.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub là nền tảng video chạy trong quá trình triển khai này, được xây dựng cho người sáng tạo, người xem, cộng đồng và nhà điều hành nền tảng.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub cung cấp các kênh của người sáng tạo, tải lên video, xuất bản theo lịch, đăng ký, nhận xét, danh sách phát, xem sau, trang nội dung trực tiếp và các công cụ quản trị từ một nền tảng.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub sử dụng cookie và bộ nhớ trình duyệt cần thiết cho các phiên đăng nhập, xác thực API, hành vi CSRF/bảo mật, chọn ngôn ngữ, chọn chủ đề, trạng thái menu tài khoản và các tính năng khác cần thiết để ứng dụng hoạt động.',
  'playhub_language, theme' => 'playhub_ngôn ngữ, chủ đề',
