  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'Quy tắc sử dụng triển khai PlayHub này với tư cách là người xem, người tạo hoặc quản trị viên.',
  'Safety' => 'An toàn',
  'Safety / technical' => 'An toàn/kỹ thuật',
  'Safety and content reports' => 'Báo cáo nội dung và an toàn',
  'Safety or report' => 'An toàn hoặc báo cáo',
  'Sample endpoints' => 'Điểm cuối mẫu',
  'sample endpoints loaded' => 'đã tải điểm cuối mẫu',
  'Schedule video' => 'Lên lịch video',
  'Scheduled video release and reminders.' => 'Phát hành video và nhắc nhở theo lịch trình.',
  'Scheduled videos' => 'Video đã lên lịch',
  'Scheduling a video release' => 'Lên lịch phát hành video',
  'Search for answers...' => 'Tìm kiếm câu trả lời...',
  'Search help articles, topics, or questions...' => 'Tìm kiếm các bài viết trợ giúp, chủ đề hoặc câu hỏi...',
  'Select a reason' => 'Chọn một lý do',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Chọn một hoặc nhiều tệp video, nhập thông tin chi tiết được yêu cầu, chọn danh mục và ngôn ngữ, thêm hình thu nhỏ, chọn chế độ hiển thị và xuất bản. Các tệp lớn được tải lên theo từng khối trước khi máy chủ bắt đầu xử lý.',
  'Send a message and it will be saved for admins.' => 'Gửi tin nhắn và nó sẽ được lưu cho quản trị viên.',
  'Send billing details to admin support for review.' => 'Gửi chi tiết thanh toán cho bộ phận hỗ trợ quản trị viên để xem xét.',
  'Send message' => 'Gửi tin nhắn',
  'Send order details through the refund popup.' => 'Gửi chi tiết đơn đặt hàng thông qua cửa sổ bật lên hoàn tiền.',
  'Send us a message' => 'Gửi tin nhắn cho chúng tôi',
  'Sending...' => 'Đang gửi...',
  'Server configured' => 'Đã định cấu hình máy chủ',
  'server records' => 'hồ sơ máy chủ',
  'Service operation' => 'Vận hành dịch vụ',
  'session, token' => 'phiên, mã thông báo',
  'Settings and login' => 'Cài đặt và đăng nhập',
  'Short summary' => 'Tóm tắt ngắn',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Đăng nhập và sử dụng Cài đặt cho tài khoản, hồ sơ, mật khẩu, thông báo, quyền riêng tư và tùy chọn của người sáng tạo. Các vấn đề về nội dung và tải lên của người sáng tạo phải bao gồm tiêu đề video, kênh, trình duyệt và mọi lỗi xử lý hiển thị trên trang tải lên.',
  'Sign in for account support' => 'Đăng nhập để được hỗ trợ tài khoản',
  'Signed in' => 'Đã đăng nhập',
  'Start uploading' => 'Bắt đầu tải lên',
  'Still can’t find an answer?' => 'Vẫn không thể tìm thấy câu trả lời?',
  'Stored for admins' => 'Được lưu trữ cho quản trị viên',
  'Stores language, theme, and interface preferences.' => 'Lưu trữ các tùy chọn về ngôn ngữ, chủ đề và giao diện.',
  'Studio, playlists, analytics, channels.' => 'Studio, danh sách phát, phân tích, kênh.',
  'Submit a billing or refund message to admin support.' => 'Gửi thông báo thanh toán hoặc hoàn tiền tới bộ phận hỗ trợ quản trị viên.',
  'Submit refund request' => 'Gửi yêu cầu hoàn tiền',
  'Submit request' => 'Gửi yêu cầu',
  'Subscription cancellation' => 'Hủy đăng ký',
  'Support dashboard' => 'Trang tổng quan hỗ trợ',
  'System status' => 'Trạng thái hệ thống',
  'Table' => 'Bảng',
  'Taxonomies' => 'Phân loại',
  'Technical issue' => 'Vấn đề kỹ thuật',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Ghi chú kỹ thuật về việc tích hợp với API PlayHub hiện tại và quy trình tải lên.',
  'Tell us more about your question or request...' => 'Hãy cho chúng tôi biết thêm về câu hỏi hoặc yêu cầu của bạn...',
  'Terms of Use' => 'Điều khoản sử dụng',
  'The configured' => 'Đã cấu hình',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Trang dành cho nhà phát triển được kết nối với phần phụ trợ trực tiếp của Laravel: khoảng không quảng cáo tuyến đường, số lượng cơ sở dữ liệu, giới hạn tải lên và siêu dữ liệu nền tảng được tải từ /api/developers.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Giao diện người dùng lưu trữ các tùy chọn như ngôn ngữ đã chọn, chủ đề, hàng phát lại, tiến trình xem và trạng thái giao diện để trải nghiệm vẫn nhất quán khi điều hướng và tải lại trang.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Công việc xử lý mã hóa các bản trình diễn, tạo hình thu nhỏ khi cần, lưu trữ chú thích và đánh dấu video sẵn sàng khi quá trình xử lý hoàn tất. Các video đã lên lịch trong tương lai vẫn ở chế độ riêng tư cho đến khi người lên lịch phát hành chúng.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Hệ thống tải lên được hỗ trợ bởi cơ sở dữ liệu, hỗ trợ các danh mục và ngôn ngữ từ API, xử lý video đã tải lên, lưu trữ hình thu nhỏ và chú thích, đồng thời giữ nội dung đã lên lịch ở chế độ riêng tư cho đến thời điểm phát hành.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Trang này giải thích cách PlayHub sử dụng cookie và bộ nhớ trình duyệt cho các phiên, bảo mật, tùy chọn, phát lại và các tính năng được xác thực.',
  'Ticket source' => 'Nguồn vé',
  'Top content categories' => 'Danh mục nội dung hàng đầu',
  'Topic' => 'chủ đề',
  'Transaction / invoice' => 'Giao dịch/hóa đơn',
  'Transaction / invoice ID' => 'ID giao dịch/hóa đơn',
  'Unable to send message.' => 'Không thể gửi tin nhắn.',
  'Unable to submit refund request.' => 'Không thể gửi yêu cầu hoàn lại tiền.',
  'Understanding admin support tickets' => 'Hiểu vé hỗ trợ quản trị viên',
  'Upload and processing help' => 'Trợ giúp tải lên và xử lý',
  'Upload chunks' => 'Tải lên các đoạn',
  'Upload issues' => 'Sự cố tải lên',
  'Upload languages' => 'Tải lên ngôn ngữ',
  'Upload limit' => 'Giới hạn tải lên',
  'Upload options' => 'Tùy chọn tải lên',
  'Upload or processing' => 'Tải lên hoặc xử lý',
  'Upload page' => 'Tải lên trang',
  'Upload pipeline' => 'Đường dẫn tải lên',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Tải lên, xem, đăng ký, kiểm duyệt và xây dựng bằng dữ liệu PlayHub trực tiếp.',
  'Uploaded videos' => 'Video đã tải lên',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Các video đã tải lên được mã hóa thành các bản trình diễn có thể phát được. Thời gian xử lý phụ thuộc vào kích thước tệp, thời lượng, tải máy chủ và trạng thái hàng đợi. Trang tải lên và Creator Studio hiển thị trạng thái xử lý thực tế từ bản ghi video.',
  'Uploads, scheduling, and processing are available.' => 'Tải lên, lập kế hoạch và xử lý có sẵn.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Sử dụng /api/video, điểm cuối kênh và tuyến đường được xác thực cho quy trình làm việc của người sáng tạo.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Sử dụng các hành động báo cáo tích hợp sẵn cho video và nhận xét để quản trị viên nhận được thông tin tham khảo nội dung chính xác. Các trang bảng điều khiển dành cho quản trị viên sử dụng dữ liệu cơ sở dữ liệu trực tiếp về người dùng, nội dung, báo cáo, kiếm tiền, phân tích, hỗ trợ, vai trò và cài đặt hệ thống.',
  'Use Contact Us' => 'Sử dụng Liên hệ với chúng tôi',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Sử dụng JSON cho các yêu cầu API thông thường và FormData để tải tệp lên. Không bỏ qua xác thực: danh mục và ngôn ngữ là ID cơ sở dữ liệu, khả năng hiển thị bị giới hạn ở chế độ công khai, không công khai hoặc riêng tư và phụ đề chấp nhận tệp SRT, VTT hoặc TXT.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Sử dụng Cài đặt để cập nhật hồ sơ, bảo mật, mật khẩu, phân phối hai yếu tố, thiết bị, tùy chọn và tùy chọn thông báo của bạn. Nếu bạn không thể truy cập tài khoản của mình, hãy sử dụng quy trình đăng nhập và cung cấp email tài khoản cho quản trị viên trang web.',
  'Use the contact form' => 'Sử dụng mẫu liên hệ',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Sử dụng các hành động báo cáo về video, nhận xét và bài đăng trên cộng đồng để quản trị viên nhận được thông tin tham khảo nội dung chính xác.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Sử dụng hành động báo cáo đối với video, nhận xét và bài đăng trên cộng đồng khi nội dung có thể vi phạm quy tắc của nền tảng. Các báo cáo này được gắn với bản ghi nội dung thực và tốt hơn một thông báo chung chung vì quản trị viên có thể xem lại mục chính xác.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Sử dụng kênh PlayHub phù hợp để nhận trợ giúp về tài khoản, báo cáo nội dung, sự cố kỹ thuật và yêu cầu của quản trị viên.',
  'Video categories' => 'Danh mục video',
  'Video for everyone. Built for creators and viewers.' => 'Video dành cho mọi người. Được xây dựng từ dữ liệu nền tảng thực.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Các vấn đề về tải lên, lên lịch, hình thu nhỏ và xử lý video.',
  'Videos, thumbnails, captions, processing.' => 'Video, hình thu nhỏ, chú thích, xử lý.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Người xem có thể duyệt các danh mục, tìm kiếm video, xem nội dung, đăng ký kênh, lưu video để xem sau, nhận xét, nhận thông báo cũng như quản lý các tùy chọn ngôn ngữ và khả năng truy cập.',
  'Viewing and community help' => 'Xem và trợ giúp cộng đồng',
  'Waiting for backend endpoint inventory.' => 'Đang chờ kiểm kê điểm cuối phụ trợ.',
  'We’re here to help.' => 'Chúng tôi ở đây để giúp đỡ.',
  'What is PlayHub?' => 'PlayHub là gì?',
  'What PlayHub does' => 'PlayHub làm gì',
  'Where do contact messages go?' => 'Tin nhắn liên lạc sẽ đi đâu?',
  'Why is my video still processing?' => 'Tại sao video của tôi vẫn đang được xử lý?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Đúng. Sử dụng trường ngày và giờ của lịch trình gốc trên trang tải lên. Phần phụ trợ lưu trữ theo lịch_at, xử lý video, giữ video ở chế độ riêng tư trong khi ngày ở trong tương lai và phát hành video khi bộ lập lịch của Laravel chạy sau thời gian đã lên lịch.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Đúng. Sử dụng trường lịch trình gốc trên Tải lên. Phần phụ trợ lưu trữ theo lịch_at và phát hành video sau khi xử lý khi đạt đến thời gian đã lên lịch.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Bạn đang duyệt với tư cách là khách. Đăng nhập để truy cập các công cụ dành riêng cho tài khoản.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Bạn chịu trách nhiệm về thông tin đăng nhập tài khoản, hoạt động hồ sơ, nội dung đã tải lên, nhận xét, tin nhắn và mọi hành động của người sáng tạo hoặc quản trị viên được thực hiện từ tài khoản của bạn. Sử dụng mật khẩu mạnh và cập nhật các phương thức phân phối hai yếu tố.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Bạn có thể xóa cookie trình duyệt và bộ nhớ cục bộ trong cài đặt trình duyệt của mình. Việc xóa bộ nhớ cần thiết có thể khiến bạn đăng xuất, đặt lại tùy chọn ngôn ngữ/chủ đề, xóa trạng thái phát lại cục bộ và yêu cầu bạn đăng nhập lại.',
  'You receive a response by email.' => 'Bạn nhận được phản hồi qua email.',
  'You’re in control' => 'Bạn nắm quyền kiểm soát',
  'Your choices' => 'Lựa chọn của bạn',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Tin nhắn của bạn được lưu trực tiếp trong phần phụ trợ của trang web và xuất hiện trong bảng điều khiển quản trị viên trong phần Hỗ trợ.',
  'Your support' => 'Hỗ trợ của bạn',
