  'View creator' => 'Xem người sáng tạo',
  'Remove from playlist' => 'Xóa khỏi danh sách phát',
  'Removing videos from playlists is not available here yet.' => 'Xóa video khỏi danh sách phát chưa khả dụng ở đây.',
  'Create New Playlist' => 'Tạo danh sách phát mới',
